package flanker

import (
	"context"

	"github.com/shibukawa/ebigentserver/examples/solo/game"
	"github.com/shibukawa/ebigentserver/session"
)

// Decide is the compiled decision list. Earlier cases take precedence,
// exactly as the chips were mined and approved.
func Decide(obs game.Observation) (game.Action, bool) {
	switch {
	case game.GapX(obs) < 0 && game.GapX(obs).Abs() <= game.GapY(obs).Abs():
		// chip quarry_left_on_narrow_axis → move_left (coverage 1133, counterexamples 0)
		return game.Action{Move: game.Left}, true
	case game.GapX(obs) > 0 && game.GapX(obs).Abs() <= game.GapY(obs).Abs():
		// chip quarry_right_on_narrow_axis → move_right (coverage 898, counterexamples 0)
		return game.Action{Move: game.Right}, true
	case game.GapY(obs) > 0 && game.GapY(obs).Abs() > game.GapX(obs).Abs():
		// chip quarry_below_on_wide_axis → move_down (coverage 447, counterexamples 0)
		return game.Action{Move: game.Down}, true
	case game.GapY(obs) > 0 && game.GapY(obs).Abs() <= game.GapX(obs).Abs():
		// chip quarry_below_on_narrow_axis → move_down (coverage 312, counterexamples 0)
		return game.Action{Move: game.Down}, true
	case game.GapY(obs) < 0 && game.GapY(obs).Abs() <= game.GapX(obs).Abs():
		// chip quarry_above_on_narrow_axis → move_up (coverage 305, counterexamples 0)
		return game.Action{Move: game.Up}, true
	case game.GapX(obs) < 0 && game.GapX(obs).Abs() >= game.GapY(obs).Abs():
		// chip quarry_left_on_wide_axis → move_left (coverage 311, counterexamples 0)
		return game.Action{Move: game.Left}, true
	case game.GapY(obs) < 0 && game.GapY(obs).Abs() > game.GapX(obs).Abs():
		// chip quarry_above_on_wide_axis → move_up (coverage 269, counterexamples 0)
		return game.Action{Move: game.Up}, true
	case game.GapX(obs) > 0 && game.GapX(obs).Abs() >= game.GapY(obs).Abs():
		// chip quarry_right_on_wide_axis → move_right (coverage 64, counterexamples 0)
		return game.Action{Move: game.Right}, true
	}
	var zero game.Action
	return zero, false
}

// Flanker seats the compiled policy behind api:agent-interface: an
// ordinary agent, indistinguishable from a hand-written bot.
type Flanker struct {
	last game.Observation
	has  bool
}

func (*Flanker) Joined(session.SlotID) {}

func (a *Flanker) Observe(obs game.Observation) { a.last, a.has = obs, true }

func (a *Flanker) Decide(context.Context) (game.Action, bool) {
	if !a.has {
		var zero game.Action
		return zero, false
	}
	return Decide(a.last)
}

func (*Flanker) Ended(session.Result) {}

// actionName maps a decided action back to its vocabulary term, for
// the generated episode-fixture tests.
func actionName(a game.Action) string {
	switch a {
	case game.Action{Move: game.Stay}:
		return "move_stay"
	case game.Action{Move: game.Up}:
		return "move_up"
	case game.Action{Move: game.Down}:
		return "move_down"
	case game.Action{Move: game.Left}:
		return "move_left"
	case game.Action{Move: game.Right}:
		return "move_right"
	}
	return ""
}
